import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as s,af as e}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"智谱清言 / Z.ai 学习地图","description":"写给谁：要选智谱对话面的前端工程师。主路径是智谱清言和 Z.ai 对话，不是 GLM Coding Plan。","frontmatter":{"title":"智谱清言 / Z.ai 学习地图","description":"写给谁：要选智谱对话面的前端工程师。主路径是智谱清言和 Z.ai 对话，不是 GLM Coding Plan。","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"zh/products/zhipu-chat/index.md","filePath":"zh/products/zhipu-chat/index.md","lastUpdated":1787110548000}'),r={name:"zh/products/zhipu-chat/index.md"};function p(l,a,i,d,o,h){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="智谱清言-z-ai-学习地图" tabindex="-1">智谱清言 / Z.ai 学习地图 <a class="header-anchor" href="#智谱清言-z-ai-学习地图" aria-label="Permalink to &quot;智谱清言 / Z.ai 学习地图&quot;">​</a></h1><blockquote><p><strong>智谱清言</strong> 是智谱的国内生成式助手。官方定义（<a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a>）： 「基于 GLM 大模型，不只是 AI 助手，更是能帮你把事办成的 Agent。」</p><p><strong>Z.ai</strong> 是同一厂商的国际对话面。官方 title（<a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a>）： 「Z.ai - Advanced AI Chatbot &amp; Agent powered by GLM-5.2」</p><p>本目录对位 Claude.ai。它<strong>不是</strong> GLM Coding Plan，也不是 ZCode / AutoClaw。编码套餐只在下面占一行。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>写给谁：</strong> 前端工程师，要先分清该打开哪个官方入口。你需要浏览器或清言 App，不需要仓库。</p><p><strong>目标：</strong> 画出官方一级 AI 产品，并带你进清言 / Z.ai 对话。</p><p><strong>非目标：</strong> Coding Plan 安装、API 快速开始、模型内部机制（链 <a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a>）、臆造每日额度或现行人民币价。</p><h2 id="产品全景" tabindex="-1">产品全景 <a class="header-anchor" href="#产品全景" aria-label="Permalink to &quot;产品全景&quot;">​</a></h2><p>智谱（公司站 <a href="https://www.zhipuai.cn/zh" target="_blank" rel="noreferrer">zhipuai.cn</a>）下面有多张 AI 皮。它们<strong>不是</strong>同一个聊天窗口。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>智谱 / Z.ai</span></span>
<span class="line"><span>├── 对话（本目录主路径）</span></span>
<span class="line"><span>│   ├── 智谱清言 — chatglm.cn、官方 App</span></span>
<span class="line"><span>│   └── Z.ai — chat.z.ai / z.ai</span></span>
<span class="line"><span>├── 编码套餐 / 桌面编码</span></span>
<span class="line"><span>│   ├── GLM Coding Plan — 给 Claude Code 等工具配额度</span></span>
<span class="line"><span>│   └── ZCode — 官方代码工具</span></span>
<span class="line"><span>├── Agent / 办公</span></span>
<span class="line"><span>│   ├── AutoGLM</span></span>
<span class="line"><span>│   └── AutoClaw（本地 OpenClaw 客户端）</span></span>
<span class="line"><span>├── 开放平台 / API</span></span>
<span class="line"><span>│   ├── BigModel（bigmodel.cn）</span></span>
<span class="line"><span>│   └── docs.z.ai</span></span>
<span class="line"><span>└── 其它官方 AI 入口（地图一行）</span></span>
<span class="line"><span>    ├── Zread.ai</span></span>
<span class="line"><span>    ├── AMiner</span></span>
<span class="line"><span>    ├── 智谱学习中心</span></span>
<span class="line"><span>    ├── 智谱 AI 输入法</span></span>
<span class="line"><span>    ├── CodeGeeX</span></span>
<span class="line"><span>    └── 开源 GLM 权重</span></span></code></pre></div><table tabindex="0"><thead><tr><th>产品</th><th>是什么</th><th>入口</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>智谱清言</strong></td><td>国内对话 / Agent 助手</td><td><a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a></td><td><a href="./zhipu-chat.html">Tutorial</a></td></tr><tr><td><strong>Z.ai 对话</strong></td><td>国际对话 / Agent 助手</td><td><a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a></td><td>同一 Tutorial</td></tr><tr><td><strong>GLM Coding Plan</strong></td><td>编码工具订阅，不是聊天安装</td><td><a href="https://z.ai/subscribe" target="_blank" rel="noreferrer">z.ai/subscribe</a>、<a href="https://bigmodel.cn/glm-coding" target="_blank" rel="noreferrer">bigmodel.cn/glm-coding</a></td><td>地图一行（#75）</td></tr><tr><td><strong>ZCode</strong></td><td>官方代码工具</td><td><a href="https://zcode.z.ai/cn" target="_blank" rel="noreferrer">zcode.z.ai/cn</a></td><td>地图一行</td></tr><tr><td><strong>AutoGLM / AutoClaw</strong></td><td>报告 / 浏览器操作 / 本地客户端</td><td><a href="https://autoglm.zhipuai.cn" target="_blank" rel="noreferrer">autoglm.zhipuai.cn</a></td><td>地图一行</td></tr><tr><td><strong>BigModel / Z.ai API</strong></td><td>模型 HTTP API</td><td><a href="https://bigmodel.cn" target="_blank" rel="noreferrer">bigmodel.cn</a>、<a href="https://docs.z.ai" target="_blank" rel="noreferrer">docs.z.ai</a></td><td>地图一行</td></tr><tr><td><strong>Zread.ai / AMiner / 学习中心 / AI 输入法</strong></td><td>公司页「原生产品」列出</td><td><a href="https://www.zhipuai.cn/zh" target="_blank" rel="noreferrer">zhipuai.cn/zh</a></td><td>地图一行；独立 URL 以公司页为准</td></tr><tr><td><strong>CodeGeeX</strong></td><td>智能编程助手（官方新闻）</td><td><a href="https://www.zhipuai.cn/en/news/20" target="_blank" rel="noreferrer">公司新闻</a></td><td>地图一行</td></tr><tr><td><strong>开源 GLM</strong></td><td>模型权重</td><td><a href="https://github.com/zai-org/GLM-5" target="_blank" rel="noreferrer">github.com/zai-org/GLM-5</a></td><td>地图一行</td></tr><tr><td>商业生态 / IR / 招聘</td><td>非 AI 产品手册</td><td>公司页</td><td><strong>非本站</strong></td></tr></tbody></table><p>官方把「在线体验」写成两个链接（<a href="https://www.zhipuai.cn/zh/research/161" target="_blank" rel="noreferrer">GLM-5.2 研究页</a>）：<strong>Z.ai = chat.z.ai</strong>，<strong>智谱清言 App/网页版 = chatglm.cn</strong>。</p><p><strong>容易撞名：</strong></p><ul><li><strong>清言 ≠ Z.ai 对话。</strong> 两个入口，两套协议主体。没有官方「一个账号打通」。</li><li><strong>ChatGLM</strong> 是历史模型 / 商店文案里的名字，不是现在要记的产品 URL。</li><li><strong>对话里写代码 ≠ GLM Coding Plan。</strong> 后者是给 Claude Code 等工具的额度，见 #75。</li><li><strong>AutoGLM ≠ AutoClaw。</strong> 公司页两者都列。</li></ul><p>细节见 <a href="./zhipu-chat-glossary.html">术语表</a>。</p><h3 id="快速决策-我该用哪个" tabindex="-1">快速决策：我该用哪个？ <a class="header-anchor" href="#快速决策-我该用哪个" aria-label="Permalink to &quot;快速决策：我该用哪个？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 在浏览器里对话 / 写作 / 看图看文档 / 做 PPT 或研究报告</span></span>
<span class="line"><span>│   ├── 人在国内、要中文产品面 → 智谱清言（chatglm.cn 或官方 App）</span></span>
<span class="line"><span>│   └── 人在国际面、页面是 Z.ai → chat.z.ai</span></span>
<span class="line"><span>├── 在 Claude Code / Cline 等工具里用 GLM 额度</span></span>
<span class="line"><span>│   └── → GLM Coding Plan（本目录不写安装）</span></span>
<span class="line"><span>├── 要官方桌面代码工具</span></span>
<span class="line"><span>│   └── → ZCode</span></span>
<span class="line"><span>├── 要报告 / 网页自动操作 / 本地小龙虾客户端</span></span>
<span class="line"><span>│   └── → AutoGLM / AutoClaw</span></span>
<span class="line"><span>└── 在自己的程序里调模型</span></span>
<span class="line"><span>    └── → BigModel 或 docs.z.ai API</span></span></code></pre></div><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>读什么</th><th>目标</th></tr></thead><tbody><tr><td>1. 选对入口</td><td>上面的决策树</td><td>不把 Coding Plan 打开当清言</td></tr><tr><td>2. 会用对话</td><td><a href="./zhipu-chat.html">智谱清言 / Z.ai 教程</a></td><td>登录、发第一条、知道芯片是什么</td></tr><tr><td>3. 回查入口</td><td><a href="./zhipu-chat-cheatsheet.html">速查表</a></td><td>URL、决策、信息源</td></tr><tr><td>4. 名字打架</td><td><a href="./zhipu-chat-glossary.html">术语表</a></td><td>清言 / Z.ai / ChatGLM / Coding Plan</td></tr></tbody></table><p>没有独立 cookbook：官方没有可引用的 How-to 文档树。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./zhipu-chat.html">智谱清言 / Z.ai 教程</a></li><li><a href="./zhipu-chat-cheatsheet.html">速查表</a></li><li><a href="./zhipu-chat-glossary.html">术语表</a></li><li><a href="./../">产品总览</a></li></ul>`,21)])])}const m=t(r,[["render",p]]);export{f as __pageData,m as default};
